var i=`1282-stewed-saltfish-with-dumplings`;var n=`world-1282`;var o=`KN`;var a=`central-america-caribbean`;var s=4;var r=1495;var l={en:`Stewed Saltfish with Dumplings`,ua:`Тушкована солона риба з кнедликами`};var d={en:`Stewed Saltfish with Dumplings is a dish from Saint Kitts and Nevis featuring salt cod, yellow onion, tomato, green bell pepper. This home-sized recipe records each ingredient at the step where it is used.`,ua:`Тушкована солона риба з кнедликами, страва кухні країни Сент-Кіттс і Невіс з такими основними складниками: солона тріска, жовта цибуля, помідор, зелений солодкий перець. У домашньому рецепті кожний продукт прив’язаний до етапу його використання.`};var u=[{en:`Soak salt cod in cold water in the refrigerator for about 24 hours, changing the water several times. Drain before simmering; never soak salted fish at room temperature.`,ua:`Вимочуйте солону тріску в холодній воді в холодильнику близько доби, кілька разів змінюючи воду. Злийте перед варінням; не вимочуйте рибу за кімнатної температури.`,t:[`soaking-dried-produce`],m:1440,i:[[`salt-cod`,600,`g`],[`water`,1300,`ml`]]},{en:`Gently cook the prepared contents in the simmering liquid from earlier steps until fully cooked and safe to eat.`,ua:`Обережно доведіть підготовлені продукти до повної готовності в гарячій рідині з попередніх етапів.`,t:[`poaching`],m:15,i:[]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 11 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 11 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:11,i:[[`yellow-onion`,170,`g`],[`tomato`,280,`g`],[`green-bell-pepper`,180,`g`],[`olive-oil`,45,`ml`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:10,i:[[`all-purpose-flour`,310,`g`],[`water`,190,`ml`]]},{en:`Cook dumplings in batches in gently boiling salted water for about 19 minutes, until they float and the filling is cooked through. Lift out with a slotted spoon.`,ua:`Варіть вироби порціями в ледь киплячій підсоленій воді приблизно 19 хвилин, доки вони спливуть і начинка приготується. Вийміть шумівкою.`,t:[`boiling`],m:19,i:[]}];var g={slug:i,id:n,country:`KN`,region:a,servings:4,minutes:r,title:l,text:d,steps:u};export{o as country,g as default,n as id,r as minutes,a as region,s as servings,i as slug,u as steps,d as text,l as title};